create or replace function public.toolbox_issues_create_subitem(p_workspace_id uuid,p_issue_id text,p_fields jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare s public.toolbox_issue_subitems%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; if not exists(select 1 from public.toolbox_issues where workspace_id=p_workspace_id and id=p_issue_id::bigint and archived_at is null) then raise exception 'Issue not found' using errcode='P0002'; end if; insert into public.toolbox_issue_subitems(workspace_id,issue_id,name,status,person,payload) values(p_workspace_id,p_issue_id::bigint,left(trim(coalesce(p_fields->>'name','New sub-task')),500),left(coalesce(nullif(p_fields->>'status',''),'Working on it'),80),coalesce(p_fields->'person','[]'::jsonb),p_fields-'name'-'status'-'person'-'personIds') returning * into s; update public.toolbox_issues set updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=p_issue_id::bigint; return private.toolbox_issue_subitem_json(s); end $$; create or replace function public.toolbox_issues_get_subitem(p_workspace_id uuid,p_subitem_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare s public.toolbox_issue_subitems%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select * into s from public.toolbox_issue_subitems where workspace_id=p_workspace_id and id=p_subitem_id::bigint; if not found then raise exception 'Sub-task not found' using errcode='P0002'; end if; return private.toolbox_issue_subitem_json(s); end $$; create or replace function public.toolbox_issues_update_subitem(p_workspace_id uuid,p_subitem_id text,p_updates jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare s public.toolbox_issue_subitems%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; update public.toolbox_issue_subitems set name=case when p_updates?'name' then left(trim(p_updates->>'name'),500) else name end,status=case when p_updates?'status' then left(p_updates->>'status',80) else status end,person=case when p_updates?'person' then coalesce(p_updates->'person','[]'::jsonb) else person end,payload=payload||(p_updates-'name'-'status'-'person'-'personIds'),version=version+1,updated_at=now() where workspace_id=p_workspace_id and id=p_subitem_id::bigint returning * into s; if not found then raise exception 'Sub-task not found' using errcode='P0002'; end if; update public.toolbox_issues set updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=s.issue_id; return private.toolbox_issue_subitem_json(s); end $$; create or replace function public.toolbox_issues_delete_subitem(p_workspace_id uuid,p_subitem_id text) returns jsonb language plpgsql security definer set search_path='' as $$ declare iid bigint; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; delete from public.toolbox_issue_subitems where workspace_id=p_workspace_id and id=p_subitem_id::bigint returning issue_id into iid; if iid is null then raise exception 'Sub-task not found' using errcode='P0002'; end if; update public.toolbox_issues set updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=iid; return jsonb_build_object('success',true); end $$; revoke execute on function public.toolbox_issues_create_subitem(uuid,text,jsonb),public.toolbox_issues_get_subitem(uuid,text),public.toolbox_issues_update_subitem(uuid,text,jsonb),public.toolbox_issues_delete_subitem(uuid,text) from public,anon; grant execute on function public.toolbox_issues_create_subitem(uuid,text,jsonb),public.toolbox_issues_get_subitem(uuid,text),public.toolbox_issues_update_subitem(uuid,text,jsonb),public.toolbox_issues_delete_subitem(uuid,text) to authenticated;;
